// ชุดข้อมูลเปิดที่ต้องเฝ้าดู (CKAN API ของ ปภ. และกรมพัฒนาที่ดิน)
const datasets = [
  { key: 'storm',     label: 'ปภ. — วาตภัย',        base: 'https://catalog.disaster.go.th', id: '32ab6f0a-142a-4b60-ab5e-7f2b057957b7' },
  { key: 'flood',     label: 'ปภ. — อุทกภัย',       base: 'https://catalog.disaster.go.th', id: 'b3f55bb3-0f35-4fda-b41c-f337aaf4f605' },
  { key: 'slide',     label: 'ปภ. — ดินโคลนถล่ม',   base: 'https://catalog.disaster.go.th', id: '016d235e-6d62-4d72-aeae-769b1ab0db31' },
  { key: 'lddflood',  label: 'LDD — น้ำท่วมซ้ำซาก', base: 'https://lddcatalog.ldd.go.th',   id: 'ldd_21_04' },
  { key: 'lddrought', label: 'LDD — แล้งซ้ำซาก',    base: 'https://lddcatalog.ldd.go.th',   id: 'lpd05' }
];

return datasets.map(d => ({
  json: { ...d, url: `${d.base}/api/3/action/package_show?id=${d.id}` }
}));

// สร้าง fingerprint ของทุกชุดข้อมูล = เวลาที่แก้ไขล่าสุดของแต่ละไฟล์
const items = $input.all();
const meta  = $('รายการชุดข้อมูล').all().map(i => i.json);
const fp = {};

items.forEach((item, i) => {
  const res = item.json.result || {};
  const key = meta[i] ? meta[i].key : res.name;
  const resources = {};
  (res.resources || [])
    .filter(r => ['CSV', 'XLS', 'XLSX'].includes(String(r.format || '').toUpperCase()))
    .forEach(r => { resources[r.id] = r.last_modified || r.created; });
  fp[key] = {
    label: meta[i] ? meta[i].label : key,
    metadata_modified: res.metadata_modified,
    resources
  };
});

return [{ json: { fingerprint: fp } }];

// เทียบ fingerprint ใหม่กับ state ที่เก็บไว้ใน repo
const current = $('สร้าง fingerprint').first().json.fingerprint;
const previous = $json && $json.storm ? $json : null;

const changes = [];
for (const [key, cur] of Object.entries(current)) {
  const old = previous ? previous[key] : null;
  if (!old) { changes.push(`${cur.label}: ยังไม่เคยบันทึก state`); continue; }
  if (old.metadata_modified !== cur.metadata_modified) {
    changes.push(`${cur.label}: ชุดข้อมูลถูกแก้ไข (${old.metadata_modified} → ${cur.metadata_modified})`);
  }
  const oldRes = old.resources || {};
  const added = Object.keys(cur.resources).filter(id => !(id in oldRes));
  const touched = Object.keys(cur.resources).filter(id => id in oldRes && oldRes[id] !== cur.resources[id]);
  if (added.length)   changes.push(`${cur.label}: มีไฟล์ใหม่ ${added.length} รายการ`);
  if (touched.length) changes.push(`${cur.label}: ไฟล์เดิมถูกอัปเดต ${touched.length} รายการ`);
}

return [{ json: {
  changed: changes.length > 0,
  changeCount: changes.length,
  changes,
  checkedAt: new Date().toISOString()
} }];

